  gap: 12px;
  position: relative;
}
.fmstr-cmp-pof-uc-v2__visual--bakery {
  background: linear-gradient(135deg, #fde68a, #fb923c);
}
.fmstr-cmp-pof-uc-v2__visual--apparel {
  background: linear-gradient(135deg, #c4b5fd, #7c3aed);
}
.fmstr-cmp-pof-uc-v2__visual--b2b {
  background: linear-gradient(135deg, #67e8f9, #0891b2);
}
.fmstr-cmp-pof-uc-v2__visual--fundraiser {
  background: linear-gradient(135deg, #86efac, #16a34a);
}
.fmstr-cmp-pof-uc-v2__visual--school {
  background: linear-gradient(135deg, #93c5fd, #1d4ed8);
}
.fmstr-cmp-pof-uc-v2__visual--custom {
  background: linear-gradient(135deg, #fda4af, #be123c);
}

.fmstr-cmp-pof-uc-v2__emoji {
  font-size: 36px;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.2));
}
.fmstr-cmp-pof-uc-v2__hint {
  display: flex;
  flex-direction: column;
  gap: 5px;
  flex: 1;
}
.fmstr-cmp-pof-uc-v2__chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  align-self: flex-start;
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.85);
  color: var(--c-fg-1);
  font-size: 11px;
  font-weight: 700;
}
.fmstr-cmp-pof-uc-v2__chip-light {
  background: rgba(255, 255, 255, 0.55);
  color: rgba(16, 24, 40, 0.85);
  font-weight: 600;
}

.fmstr-cmp-pof-uc-v2__meta {
  padding: 18px 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.fmstr-cmp-pof-uc-v2__name {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  color: var(--c-fg-1);
}
.fmstr-cmp-pof-uc-v2__desc {
  margin: 0;
  font-size: 14.5px;
  line-height: 1.6;
  color: var(--c-fg-2);
  flex: 1;
}
.fmstr-cmp-pof-uc-v2__cta {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 6px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--c-violet-600);
}
.fmstr-cmp-pof-uc-v2__card:hover .fmstr-cmp-pof-uc-v2__cta {
  gap: 8px;
}

@media (max-width: 980px) {
  .fmstr-cmp-pof-uc-v2__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 760px) {
  .fmstr-cmp-pof-uc-v2 {
    padding: 64px 16px;
  }
}
@media (max-width: 540px) {
  .fmstr-cmp-pof-uc-v2__grid {
    grid-template-columns: 1fr;
  }
}

/* host-link-override */
.fmstr-cmp-pof-hiw a {
  text-decoration: none !important;
}

.fmstr-cmp-pof-hiw {
  --c-bg: #ffffff;
  --c-soft: #f9fafb;
  --c-tint: #f7f3ff;
  --c-edge: #e4d7ff;
  --c-fg-1: #101828;
  --c-fg-2: #475467;
  --c-fg-3: #697586;
  --c-violet-100: #ede4ff;
  --c-violet-300: #c4b1ee;
  --c-violet-500: #7f56d9;
  --c-violet-600: #6941c6;
  --c-violet-700: #5b34b1;
  --c-border: #eaecf0;
  --c-border-soft: #f2f4f7;
  --c-success: #12b76a;
  --c-warning: #f79009;
  --c-shadow-sm: 0 1px 3px rgba(16, 24, 40, 0.05), 0 1px 2px rgba(16, 24, 40, 0.03);
  --c-shadow-md: 0 8px 24px rgba(16, 24, 40, 0.06);

  background: var(--c-soft);
  padding: 88px 24px;
  font-family: inherit;
  color: var(--c-fg-1);
  overflow-x: hidden;
}
.fmstr-cmp-pof-hiw *,
.fmstr-cmp-pof-hiw *::before,
.fmstr-cmp-pof-hiw *::after {
  box-sizing: border-box;
}
.fmstr-cmp-pof-hiw__step,
.fmstr-cmp-pof-hiw__content,
.fmstr-cmp-pof-hiw__visual {
  min-width: 0;
}
.fmstr-cmp-pof-hiw__visual {
  max-width: 100%;
  overflow: hidden;
}

.fmstr-cmp-pof-hiw__container {
  max-width: 1100px;
  margin: 0 auto;
}

.fmstr-cmp-pof-hiw__header {
  max-width: 760px;
  margin: 0 auto 56px;
  text-align: center;
}

.fmstr-cmp-pof-hiw__eyebrow {
  display: inline-block;
  margin: 0 0 14px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--c-violet-100);
  color: var(--c-violet-700);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.fmstr-cmp-pof-hiw__h2 {
  margin: 0 0 14px;
  font-size: clamp(28px, 3.5vw, 40px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  font-weight: 700;
  color: var(--c-fg-1);
}

.fmstr-cmp-pof-hiw__sub {
  margin: 0;
  font-size: 17px;
  line-height: 1.6;
  color: var(--c-fg-2);
}

.fmstr-cmp-pof-hiw__timeline {
  list-style: none;
  margin: 0;
  padding: 0;
}

.fmstr-cmp-pof-hiw__step {
  position: relative;
  display: grid;
  grid-template-columns: 72px 1fr 380px;
  gap: 24px;
  padding-bottom: 56px;
  align-items: start;
}
.fmstr-cmp-pof-hiw__step:last-child {
  padding-bottom: 0;
}

.fmstr-cmp-pof-hiw__step::before {
  content: '';
  position: absolute;
  left: 35px;
  top: 56px;
  bottom: 0;
  width: 2px;
  background: repeating-linear-gradient(to bottom, var(--c-violet-300) 0 6px, transparent 6px 12px);
}
.fmstr-cmp-pof-hiw__step:last-child::before {
  display: none;
}

.fmstr-cmp-pof-hiw__marker {
  width: 72px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

.fmstr-cmp-pof-hiw__num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: linear-gradient(135deg, var(--c-violet-500) 0%, var(--c-violet-700) 100%);
  color: #ffffff;
  font-size: 20px;
  font-weight: 700;
  flex-shrink: 0;
  box-shadow:
    0 6px 16px rgba(127, 86, 217, 0.28),
    0 0 0 6px var(--c-violet-100);
}

.fmstr-cmp-pof-hiw__content {
  padding-top: 8px;
}

.fmstr-cmp-pof-hiw__h3 {
  margin: 0 0 10px;
  font-size: 22px;
  line-height: 1.3;
  letter-spacing: -0.01em;
  font-weight: 700;
  color: var(--c-fg-1);
}

.fmstr-cmp-pof-hiw__body {
  margin: 0;
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--c-fg-2);
}
.fmstr-cmp-pof-hiw__body strong {
  color: var(--c-fg-1);
  font-weight: 600;
}

.fmstr-cmp-pof-hiw__visual {
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 16px;
  box-shadow: var(--c-shadow-md);
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  z-index: 1;
}

/* Mockup primitives */
.fmstr-cmp-pof-hiw__mock-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--c-fg-3);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin: 0;
}

/* Step 1: Drag element */
.fmstr-cmp-pof-hiw__palette {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  background: var(--c-soft);
  border-radius: 10px;
}
.fmstr-cmp-pof-hiw__field {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  font-size: 13px;
  color: var(--c-fg-2);
}
.fmstr-cmp-pof-hiw__field--active {
  border-color: var(--c-violet-500);
  background: var(--c-tint);
  color: var(--c-violet-700);
  font-weight: 600;
  box-shadow: 0 4px 12px rgba(127, 86, 217, 0.15);
  transform: translateX(4px);
}
.fmstr-cmp-pof-hiw__field-icon {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  background: var(--c-violet-100);
  color: var(--c-violet-700);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.fmstr-cmp-pof-hiw__dropzone {
  border: 2px dashed var(--c-violet-300);
  border-radius: 10px;
  padding: 14px;
  background: rgba(247, 243, 255, 0.5);
  font-size: 12px;
  color: var(--c-violet-700);
  font-weight: 600;
  text-align: center;
}

/* Step 2: Product with variants */
.fmstr-cmp-pof-hiw__product {
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 12px;
  align-items: center;
}
.fmstr-cmp-pof-hiw__product-img {
  width: 64px;
  height: 64px;
  border-radius: 10px;
  background: linear-gradient(135deg, #fde68a 0%, #f59e0b 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  flex-shrink: 0;
}
.fmstr-cmp-pof-hiw__product-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--c-fg-1);
  margin: 0 0 2px;
}
.fmstr-cmp-pof-hiw__product-price {
  font-size: 13px;
  color: var(--c-fg-2);
  margin: 0;
}
.fmstr-cmp-pof-hiw__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}
.fmstr-cmp-pof-hiw__pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 8px;
  border: 1px solid var(--c-border);
  font-size: 12px;
  font-weight: 600;
  color: var(--c-fg-2);
  background: #ffffff;
}
.fmstr-cmp-pof-hiw__pill--active {
  background: var(--c-violet-600);
  color: #ffffff;
  border-color: var(--c-violet-600);
}
.fmstr-cmp-pof-hiw__color {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.08);
}

/* Step 3: Stock per variant table */
.fmstr-cmp-pof-hiw__table {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  border: 1px solid var(--c-border);
  border-radius: 10px;
  overflow: hidden;
}
.fmstr-cmp-pof-hiw__th,
.fmstr-cmp-pof-hiw__td {
  padding: 9px 12px;
  font-size: 13px;
  border-bottom: 1px solid var(--c-border);
}
.fmstr-cmp-pof-hiw__th {
  background: var(--c-soft);
  color: var(--c-fg-3);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.fmstr-cmp-pof-hiw__td {
  color: var(--c-fg-1);
  font-weight: 600;
}
.fmstr-cmp-pof-hiw__table > div:nth-last-child(-n + 3) {
  border-bottom: 0;
}
.fmstr-cmp-pof-hiw__td--muted {
  color: var(--c-fg-3);
  font-weight: 400;
}
.fmstr-cmp-pof-hiw__badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
}
.fmstr-cmp-pof-hiw__badge--ok {
  background: #d1fadf;
  color: #027a48;
}
.fmstr-cmp-pof-hiw__badge--out {
  background: #fef0c7;
  color: #b54708;
}
.fmstr-cmp-pof-hiw__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.fmstr-cmp-pof-hiw__dot--ok {
  background: var(--c-success);
}

/* Step 4: Submissions */
.fmstr-cmp-pof-hiw__order {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  padding: 12px;
  background: var(--c-soft);
  border-radius: 10px;
  align-items: center;
}
.fmstr-cmp-pof-hiw__avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--c-violet-300), var(--c-violet-600));
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
}
.fmstr-cmp-pof-hiw__order-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.fmstr-cmp-pof-hiw__order-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--c-fg-1);
  margin: 0;
}
.fmstr-cmp-pof-hiw__order-sub {
  font-size: 12px;
  color: var(--c-fg-3);
  margin: 0;
}
.fmstr-cmp-pof-hiw__order-total {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}
.fmstr-cmp-pof-hiw__order-amt {
  font-size: 13px;
  font-weight: 700;
  color: var(--c-fg-1);
}

/* Responsive */
@media (max-width: 880px) {
  .fmstr-cmp-pof-hiw__step {
    grid-template-columns: 56px 1fr;
    gap: 16px;
    row-gap: 16px;
    padding-bottom: 48px;
  }
  .fmstr-cmp-pof-hiw__step::before {
    left: 27px;
    top: 48px;
  }
  .fmstr-cmp-pof-hiw__marker {
    width: 56px;
  }
  .fmstr-cmp-pof-hiw__num {
    width: 48px;
    height: 48px;
    font-size: 17px;
    box-shadow:
      0 6px 16px rgba(127, 86, 217, 0.28),
      0 0 0 5px var(--c-violet-100);
  }
  .fmstr-cmp-pof-hiw__visual {
    grid-column: 1 / -1;
    margin-left: 0;
  }
}
@media (max-width: 760px) {
  .fmstr-cmp-pof-hiw {
    padding: 64px 16px;
  }
  .fmstr-cmp-pof-hiw__h3 {
    font-size: 19px;
  }
  .fmstr-cmp-pof-hiw__visual {
    padding: 14px;
  }
}
@media (max-width: 540px) {
  .fmstr-cmp-pof-hiw__step {
    grid-template-columns: 44px 1fr;
    gap: 12px;
  }
  .fmstr-cmp-pof-hiw__step::before {
    left: 21px;
    top: 42px;
  }
  .fmstr-cmp-pof-hiw__marker {
    width: 44px;
  }
  .fmstr-cmp-pof-hiw__num {
    width: 40px;
    height: 40px;
    font-size: 14px;
    border-radius: 11px;
    box-shadow:
      0 4px 12px rgba(127, 86, 217, 0.28),
      0 0 0 4px var(--c-violet-100);
  }
  .fmstr-cmp-pof-hiw__visual {
    padding: 12px;
  }
  .fmstr-cmp-pof-hiw__product {
    grid-template-columns: 56px 1fr;
    gap: 10px;
  }
  .fmstr-cmp-pof-hiw__product-img {
    width: 56px;
    height: 56px;
    font-size: 26px;
  }
  .fmstr-cmp-pof-hiw__th,
  .fmstr-cmp-pof-hiw__td {
    padding: 7px 9px;
    font-size: 12px;
  }
  .fmstr-cmp-pof-hiw__order {
    padding: 10px;
    gap: 8px;
  }
  .fmstr-cmp-pof-hiw__h3 {
    font-size: 18px;
  }
  .fmstr-cmp-pof-hiw__body {
    font-size: 14.5px;
  }
}

/* host-link-override */
.fmstr-cmp-pof-pay a {
  text-decoration: none !important;
}

.fmstr-cmp-pof-pay {
  --c-bg: #ffffff;
  --c-tint: #f7f3ff;
  --c-edge: #e4d7ff;
  --c-fg-1: #101828;
  --c-fg-2: #475467;
  --c-fg-3: #697586;
  --c-violet-500: #7f56d9;
  --c-violet-600: #6941c6;
  --c-violet-700: #5b34b1;
  --c-border: #eaecf0;
  --c-shadow-sm: 0 1px 3px rgba(16, 24, 40, 0.05), 0 1px 2px rgba(16, 24, 40, 0.03);
  --c-shadow-md: 0 4px 20px rgba(16, 24, 40, 0.06);

  background: #ffffff;
  padding: 80px 24px;
  font-family: inherit;
  color: var(--c-fg-1);
}
.fmstr-cmp-pof-pay *,
.fmstr-cmp-pof-pay *::before,
.fmstr-cmp-pof-pay *::after {
  box-sizing: border-box;
}

.fmstr-cmp-pof-pay__container {
  max-width: 980px;
  margin: 0 auto;
}

.fmstr-cmp-pof-pay__header {
  max-width: 760px;
  margin: 0 auto 48px;
  text-align: center;
}

.fmstr-cmp-pof-pay__h2 {
  margin: 0 0 14px;
  font-size: clamp(28px, 3.5vw, 40px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  font-weight: 700;
  color: var(--c-fg-1);
}

.fmstr-cmp-pof-pay__sub {
  margin: 0;
  font-size: 17px;
  line-height: 1.6;
  color: var(--c-fg-2);
}

.fmstr-cmp-pof-pay__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.fmstr-cmp-pof-pay__card {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 32px;
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 16px;
  box-shadow: var(--c-shadow-sm);
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}
.fmstr-cmp-pof-pay__card:hover {
  border-color: var(--c-edge);
  box-shadow: var(--c-shadow-md);
  transform: translateY(-2px);
}

.fmstr-cmp-pof-pay__logo {
  height: 40px;
  min-width: 80px;
  padding: 0 14px;
  border-radius: 10px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  align-self: flex-start;
  font-weight: 700;
  font-size: 17px;
  line-height: 1;
  letter-spacing: -0.02em;
}
.fmstr-cmp-pof-pay__logo--stripe {
  color: #635bff;
}
.fmstr-cmp-pof-pay__logo--stripe svg {
  display: block;
  height: 22px;
  width: auto;
}
.fmstr-cmp-pof-pay__logo--paypal {
  color: #003087;
  font-style: italic;
  letter-spacing: -0.04em;
}
.fmstr-cmp-pof-pay__logo--paypal .fmstr-cmp-pof-pay__brand-light {
  color: #009cde;
}
.fmstr-cmp-pof-pay__logo--authnet {
  color: #1b5e9f;
  font-size: 14px;
  letter-spacing: -0.01em;
}

.fmstr-cmp-pof-pay__sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.fmstr-cmp-pof-pay__body {
  margin: 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--c-fg-2);
}

.fmstr-cmp-pof-pay__note {
  margin: 28px auto 0;
  max-width: 760px;
  padding: 18px 22px;
  background: var(--c-tint);
  border: 1px solid var(--c-edge);
  border-radius: 12px;
  font-size: 14.5px;
  line-height: 1.6;
  color: var(--c-fg-2);
  text-align: center;
}
.fmstr-cmp-pof-pay__note strong {
  color: var(--c-violet-700);
  font-weight: 600;
}

@media (max-width: 1000px) {
  .fmstr-cmp-pof-pay__grid {
    grid-template-columns: 1fr;
    max-width: 520px;
    margin: 0 auto;
  }
}
@media (max-width: 760px) {
  .fmstr-cmp-pof-pay {
    padding: 56px 16px;
  }
  .fmstr-cmp-pof-pay__card {
    padding: 24px;
  }
}

/* host-link-override */
.fmstr-cmp-pof-var-v2 a {
  text-decoration: none !important;
}

.fmstr-cmp-pof-var-v2 {
  --c-bg: #ffffff;
  --c-soft: #f9fafb;
  --c-tint: #f7f3ff;
  --c-edge: #e4d7ff;
  --c-fg-1: #101828;
  --c-fg-2: #475467;
  --c-fg-3: #697586;
  --c-violet-100: #ede4ff;
