  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 20px;
  padding: 24px;
  box-shadow: var(--c-shadow-lg);
}
.fmstr-cmp-pof-var-v2__img {
  height: 180px;
  border-radius: 14px;
  background: linear-gradient(135deg, #fde68a 0%, #f59e0b 100%);
