  font-weight: 700;
}
.fmstr-cmp-pof-var-v2__price {
  margin: 0 0 20px;
  font-size: 15px;
  color: var(--c-fg-3);
  font-weight: 600;
}
.fmstr-cmp-pof-var-v2__price strong {
  color: var(--c-violet-700);
  font-weight: 700;
}

.fmstr-cmp-pof-var-v2__row {
  margin-bottom: 16px;
}
.fmstr-cmp-pof-var-v2__row-label {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}
.fmstr-cmp-pof-var-v2__row-label-text {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-fg-3);
  text-transform: uppercase;
