  color: var(--c-fg-3);
}

.fmstr-cmp-pof-var-v2__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.fmstr-cmp-pof-var-v2__pill {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 10px;
  border: 1.5px solid var(--c-border);
  font-size: 13px;
  font-weight: 600;
  color: var(--c-fg-2);
  background: #ffffff;
}
.fmstr-cmp-pof-var-v2__pill--active {
  background: var(--c-violet-600);
  color: #ffffff;
  border-color: var(--c-violet-600);
}
.fmstr-cmp-pof-var-v2__pill--soldout {
  background: var(--c-soft);
  color: var(--c-fg-3);
  text-decoration: line-through;
  opacity: 0.65;
}
.fmstr-cmp-pof-var-v2__pill--soldout::after {
  content: 'Sold out';
  position: absolute;
  top: -8px;
  right: -8px;
  background: #fef0c7;
  color: #b54708;
  font-size: 9.5px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 999px;
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.fmstr-cmp-pof-var-v2__color {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.08);
}

.fmstr-cmp-pof-var-v2__stock-bar {
  margin-top: 16px;
  padding: 12px;
  background: rgba(247, 243, 255, 0.6);
  border: 1px solid var(--c-edge);
  border-radius: 10px;
  font-size: 12.5px;
  color: var(--c-violet-700);
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}
.fmstr-cmp-pof-var-v2__stock-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-violet-500);
  animation: vsPulse 2s ease-in-out infinite;
}
@keyframes vsPulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(1.4);
  }
}

@media (max-width: 980px) {
