  justify-content: center;
}
.fmstr-cmp-testimonials__agg-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: var(--c-fg-2);
}
.fmstr-cmp-testimonials__agg-stars {
  color: var(--c-amber-400);
  display: inline-flex;
  gap: 1px;
}
